use std::fs::{self, OpenOptions};
use std::io::Write;
use std::path::{Path, PathBuf};

#[cfg(unix)]
use std::os::unix::fs::{OpenOptionsExt, PermissionsExt};

use rand::RngExt;
use thiserror::Error;

use crate::config::Config;

const HEADER: &str = "\
# Strelitzia server configuration, generated by `strelitzia config generate`.
# Precedence: defaults < this file < STRELITZIA_* environment variables < --listen.
";

/// Writes a configuration file populated with the default settings and newly
/// generated admin/session secrets.
pub fn generate(output: &Path, force: bool) -> Result<(), GenerateError> {
    let config = Config {
        admin_token: Some(random_hex()),
        session_secret: Some(random_hex()),
        ..Config::default()
    };

    let contents = format!("{HEADER}{}", toml::to_string_pretty(&config)?);

    if let Some(parent) = output
        .parent()
        .filter(|parent| !parent.as_os_str().is_empty())
    {
        fs::create_dir_all(parent)?;
    }

    let mut options = OpenOptions::new();
    options.write(true).create(true);
    if force {
        options.truncate(true);
    } else {
        options.create_new(true);
    }
    #[cfg(unix)]
    options.mode(0o600);

    let mut file = match options.open(output) {
        Ok(file) => file,
        Err(error) if error.kind() == std::io::ErrorKind::AlreadyExists => {
            return Err(GenerateError::Exists {
                path: output.to_path_buf(),
            });
        }
        Err(error) => return Err(error.into()),
    };

    // Existing files keep their mode when truncated, so enforce 0600 explicitly.
    #[cfg(unix)]
    file.set_permissions(fs::Permissions::from_mode(0o600))?;

    file.write_all(contents.as_bytes())?;
    file.sync_all()?;

    println!("wrote configuration to {}", output.display());
    println!(
        "admin token: {}",
        config.admin_token.as_deref().unwrap_or_default()
    );

    Ok(())
}

fn random_hex() -> String {
    let mut bytes = [0u8; 32];
    rand::rng().fill(&mut bytes);
    hex::encode(bytes)
}

#[derive(Debug, Error)]
pub enum GenerateError {
    #[error("configuration file `{path}` already exists; pass --force to overwrite it")]
    Exists { path: PathBuf },
    #[error(transparent)]
    Io(#[from] std::io::Error),
    #[error("failed to serialize configuration: {0}")]
    Serialize(#[from] toml::ser::Error),
}
